import re, json, datetime
from decimal import Decimal, ROUND_HALF_UP
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
MONTHS = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
CUR = [('debtTL', 'Türk Lirası'), ('debtUSD', 'Dolar'), ('debtEUR', 'Euro'), ('debtGBP', 'İngiliz Sterlini')]
UNIT = dict(debtTL=('Türk Lirası', 'lira', 'kuruş'), debtUSD=('dolar', 'dolar', 'sent'), debtEUR=('Euro', 'Euro', 'sent'), debtGBP=('İngiliz Sterlini', 'İngiliz Sterlini', 'peni'))
def w3(n):
    h, t, o = n // 100, (n // 10) % 10, n % 10
    out = []
    if h:
        out.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if t:
        out.append(TENS[t])
    if o:
        out.append(ONES[o])
    return ' '.join(out)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for size, name in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        q = n // size
        if q:
            if size == 1000 and q == 1:
                parts.append('bin')
            else:
                parts.append(w3(q) if q < 1000 else words(q))
                parts.append(name)
            n = n % size
    if n:
        parts.append(w3(n))
    return ' '.join(p for p in parts if p)
def dec(x):
    try:
        return Decimal(str(x)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    except Exception:
        return Decimal('0')
def money(x, key):
    d = dec(x)
    whole = int(d)
    frac = int((d - whole) * 100)
    full, unit, sub = UNIT[key]
    if frac == 0:
        return words(whole) + ' ' + full
    return words(whole) + ' ' + unit + ' ' + words(frac) + ' ' + sub
def cop(phrase):
    p = str(phrase).rstrip()
    low = p.lower()
    vow = [ch for ch in low if ch in 'aeıioöuü']
    v = vow[-1] if vow else 'e'
    suf = dict(a='ı', ı='ı', e='i', i='i', o='u', u='u', ö='ü', ü='ü')[v]
    d = 't' if low and low[-1] in 'fstkçşhp' else 'd'
    sep = "'" if (p[-1:].isdigit()) else ''
    return p + sep + d + suf + 'r'
def num_last_word(n):
    return words(n).split()[-1]
def pdate(s):
    s = str(s or '').strip()
    m = re.fullmatch(r'(\d{1,2})\.(\d{1,2})\.(\d{4})', s)
    if not m:
        return None
    try:
        return datetime.date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
    except Exception:
        return None
def sdate(d):
    return str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)
def sdate_cop(d):
    w = num_last_word(d.year)
    return str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year) + "'" + cop(w)[len(w):]
def today():
    s = str(vars.get('now') or '')
    m = re.match(r'(\d{4})-(\d{2})-(\d{2})', s)
    if m:
        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    return None
def digits_spoken(s):
    return ' '.join(DIG[int(ch)] for ch in str(s) if ch.isdigit())
def body_of(prefix):
    raw = vars.get(prefix + '_data')
    if isinstance(raw, str) and raw.strip().startswith('{'):
        try:
            raw = json.loads(raw)
        except Exception:
            raw = None
    if isinstance(raw, dict):
        return raw
    return None
def ok_rc(prefix):
    return str(vars.get(prefix + '_rc') or '').strip() == '1'
def jl(name):
    v = vars.get(name)
    if isinstance(v, list):
        return v
    try:
        v = json.loads(str(v or '[]'))
        return v if isinstance(v, list) else []
    except Exception:
        return []
def card_name(c):
    n = str(c.get('productName') or '').strip()
    if not n or len(n.split()) > 5 or len(n) > 40:
        return ''
    return n
def card_intro(c):
    n = card_name(c)
    base = 'Sonu ' + digits_spoken(c.get('cardNumberLast4') or '') + ' ile biten '
    return base + (n + ' ' if n else '')
def norm(s):
    s = str(s or '').replace('İ', 'i').replace('I', 'ı').lower()
    s = s.replace('yildiz', 'yıldız')
    return re.sub(r'\s+', ' ', re.sub(r'[^0-9a-zçğıöşü ]', ' ', s)).strip()
NUMW = dict(sıfır=0, bir=1, iki=2, üç=3, dört=4, beş=5, altı=6, yedi=7, sekiz=8, dokuz=9)
TENW = dict(on=10, yirmi=20, otuz=30, kırk=40, elli=50, altmış=60, yetmiş=70, seksen=80, doksan=90)
def said_digits(s):
    low = norm(s)
    out = ''
    toks = low.split()
    i = 0
    while i < len(toks):
        t = toks[i]
        if t.isdigit():
            out += t
        elif t in TENW:
            v = TENW[t]
            if i + 1 < len(toks) and toks[i + 1] in NUMW and NUMW[toks[i + 1]] > 0:
                v += NUMW[toks[i + 1]]
                i += 1
            out += str(v)
        elif t in NUMW:
            out += str(NUMW[t])
        i += 1
    return out
def names_list(cards):
    ns = []
    for c in cards:
        n = card_name(c) or ('sonu ' + digits_spoken(c.get('cardNumberLast4') or '') + ' ile biten kartınız')
        if n not in ns:
            ns.append(n)
    if len(ns) == 1:
        return ns[0]
    return ', '.join(ns[:-1]) + ' ve ' + ns[-1]
def examples(cards):
    ns = []
    for c in cards:
        n = card_name(c)
        if n and n not in ns:
            ns.append(n)
    return ns[:2]
def select_question(cards):
    ex = examples(cards)
    q = 'Hangi kartınızın borcunu öğrenmek istersiniz?'
    if len(ex) == 2:
        q += ' Örneğin, ' + ex[0] + ' veya ' + ex[1] + ' diyebilirsiniz.'
    elif len(ex) == 1:
        q += ' Örneğin, ' + ex[0] + ' diyebilirsiniz.'
    return q

def offer_line():
    if str(vars.get('email_state')) == 'ok':
        return 'Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.'
    return 'Hesap kesim tarihinizi değiştirebilirim.'

try:
    d = body_of('bal')
    if d is None or not ok_rc('bal'):
        vars['route'] = 'error'
    else:
        try:
            c = json.loads(str(vars.get('sel_card') or '{}'))
        except Exception:
            c = dict()
        if not c.get('cardNumberLast4'):
            c['cardNumberLast4'] = str(d.get('cardNumberLast4') or '')
        if not c.get('productName'):
            c['productName'] = str(d.get('productName') or '')
        intro = card_intro(c)
        t = today()
        st = pdate(d.get('statementDate'))
        due = pdate(d.get('lastPayDate'))
        nst = pdate(d.get('nextStatementDate'))
        blocks = [(k, nm, d.get(k)) for k, nm in CUR]
        present = [(k, nm, b) for k, nm, b in blocks if isinstance(b, dict) and b]
        tl = d.get('debtTL') if isinstance(d.get('debtTL'), dict) else dict()
        vars['stmt_date_raw'] = str(d.get('statementDate') or '')
        def nodebt_sentence(names):
            if not names:
                return ''
            if len(names) == 1:
                return names[0] + ' borcunuz bulunmamaktadır.'
            return ', '.join(names[:-1]) + ' ve ' + names[-1] + ' borcunuz bulunmamaktadır.'
        def autopay():
            if str(d.get('automaticPaymentFlag') or '').upper() == 'Y' and due and t and t > due and dec(tl.get('remainAutomaticPaymentAmount')) > 0:
                return ' Otomatik ödeme talimatınızdan tahsil edilecek kalan tutar ' + cop(money(tl.get('remainAutomaticPaymentAmount'), 'debtTL')) + '.'
            return ''
        status = str(d.get('statementPaymentStatus') or '').upper()
