                    text += ' Toplam ' + nm + ' borcunuz ' + cop(money(b.get('totalDebt'), k)) + '.'
                else:
                    clear.append(nm)
            if len(clear) < len(present):
                if clear:
                    text += ' ' + nodebt_sentence(clear)
            else:
                text = intro + 'kartınız için hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek. Toplam borcunuz bulunmamaktadır.'
                mode = 'nodebt'
        elif status == 'NO_DEBT':
            text = intro + 'kartınızın ' + sdate(st) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
            tot = dec(tl.get('totalDebt'))
            if tot > 0:
                text += ' Gelecek dönemler dahil toplam borcunuz ' + cop(money(tl.get('totalDebt'), 'debtTL')) + '.'
            if due:
                text += ' Son ödeme tarihiniz ' + sdate(due) + ' olacaktır.'
            mode = 'nodebt'
        elif due and t and t > due:
            text = intro + 'kartınıza ait ' + sdate(st) + ' tarihinde kesilen ekstrenin son ödeme tarihi olan ' + sdate(due) + ' geçmiştir.'
            clear = []
