                sd = money(b.get('statementDebt'), k)
                mp = money(b.get('minPayment'), k)
                rem = money(b.get('remainingDebt'), k)
                rmp_v = dec(b.get('remainingMinPayment'))
                rmp = money(b.get('remainingMinPayment'), k)
                if k == 'debtTL':
                    if rmp_v > 0 and rmp_v >= dec(b.get('minPayment')):
                        s = 'Türk Lirası borcunuz ' + sd + ', ödenmesi gereken minimum tutar ' + cop(mp) + '.'
