                        s = 'Türk Lirası borcunuz ' + sd + ', kalan toplam borcunuz ' + cop(rem) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
                    else:
                        s = 'Türk Lirası borcunuz ' + sd + ', ödenmesi gereken minimum tutar ' + mp + ', kalan toplam borcunuz ' + rem + ', kalan minimum ödeme tutarınız ' + cop(rmp) + '.'
                else:
                    s = nm + ' borcunuz ' + sd + ', kalan toplam borcunuz ' + rem + ', ödenmesi gereken minimum tutar ' + cop(mp) + '.'
                parts.append(s)
            if not parts:
                text = intro + 'kartınızın ' + sdate(st) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
                tot = dec(tl.get('totalDebt'))
                if tot > 0:
                    text += ' Gelecek dönemler dahil toplam borcunuz ' + cop(money(tl.get('totalDebt'), 'debtTL')) + '.'
                if due:
                    text += ' Son ödeme tarihiniz ' + sdate(due) + ' olacaktır.'
                mode = 'nodebt'
            else:
                text = intro + 'kartınıza ait ' + sdate(st) + ' tarihinde kesilen ekstre ' + parts[0]
                for s in parts[1:]:
                    text += ' ' + s
                if clear:
                    text += ' ' + nodebt_sentence(clear)
                text += autopay()
                if due and t and t == due:
                    text += ' Borçlarınız için son ödeme tarihiniz bugündür.'
                elif due:
                    text += ' Borçlarınız için son ödeme tarihiniz ' + sdate_cop(due) + '.'
        read = jl('read_cards')
        if c.get('cardNumber') and c.get('cardNumber') not in read:
            read.append(c.get('cardNumber'))
        vars['read_cards'] = json.dumps(read)
        main = jl('main_cards')
        others = [x for x in main if x.get('cardNumber') not in read]
        vars['other_cards'] = json.dumps(others, ensure_ascii=False)
        vars['reading_text'] = text
        vars['read_mode'] = mode
        if others:
            vars['say_text'] = text + ' Başka bir kartınızın borcunu öğrenmek ister misiniz?'
            vars['menu_state'] = 'other_card'
            vars['route'] = 'menu'
        elif mode == 'nodebt':
            vars['say_text'] = text
            vars['route'] = 'read_end'
        elif str(vars.get('email_state')) == 'error':
            vars['say_text'] = text
            vars['route'] = 'read_error'
        else:
            vars['say_text'] = text + ' ' + offer_line()
            vars['menu_state'] = 'offer'
            vars['route'] = 'menu'
except Exception:
    vars['route'] = 'error'

